def seed_payment_methods_and_orders(apps, schema_editor):
    PaymentMethod = apps.get_model('store', 'PaymentMethod')
    Order = apps.get_model('store', 'Order')
    Payment = apps.get_model('store', 'Payment')
    invoice, _ = PaymentMethod.objects.get_or_create(code='invoice', defaults={'name': 'Получить счёт', 'kind': 'invoice', 'sort_order': 10})
    PaymentMethod.objects.get_or_create(code='online', defaults={'name': 'Оплатить онлайн', 'kind': 'online', 'sort_order': 20})
    for order in Order.objects.prefetch_related('items'):
        items = list(order.items.all())
        known_weight = all(item.weight_kg is not None for item in items)
        known_volume = all(item.volume_m3 is not None for item in items)
        order.payment_method = invoice
        order.payment_method_name = invoice.name
        order.payment_status = 'paid' if order.status in {'paid', 'done'} else 'pending'
        order.stored_total_weight_kg = sum((item.weight_kg * item.quantity for item in items), Decimal('0')) if known_weight else None
        order.stored_total_volume_m3 = sum((item.volume_m3 * item.quantity for item in items), Decimal('0')) if known_volume else None
        order.save(update_fields=['payment_method', 'payment_method_name', 'payment_status', 'stored_total_weight_kg', 'stored_total_volume_m3'])
        Payment.objects.create(order=order, payment_method=invoice, idempotency_key=uuid4().hex, amount=order.total, status=order.payment_status)


def unseed_payment_methods(apps, schema_editor):
    apps.get_model('store', 'Payment').objects.all().delete()


